                    environment: 'node',
                    fileParallelism: false,
                    include: ['vite.config.test.ts', 'src/**/*.node.test.ts'],
                    isolate: false,
                    maxWorkers: TEST_WORKERS,
                    name: 'unit',
                    sequence: { groupOrder: NODE_TEST_GROUP_ORDER },
